<?php /* A card for one application case: cover, the job it belongs to, title and summary. Same shape as a news card. */ $cardHub = bl_application_hub((string) $case['hub']); ?>
<article class="bl-news-card"><a class="bl-news-card-image" href="<?= bl_escape(bl_case_url($case)) ?>"><img src="<?= bl_escape($case['image']) ?>" alt="<?= bl_escape($case['title']) ?>" width="1000" height="660" loading="lazy"><span class="bl-card-arrow"><?= bl_icon('arrow-up-right') ?></span></a><div class="bl-news-meta"><span><?= bl_escape($cardHub ? $cardHub['title'] : 'Application') ?></span><time datetime="<?= bl_escape($case['date']) ?>"><?= date('d M Y', strtotime($case['date'])) ?></time></div><h2><a href="<?= bl_escape(bl_case_url($case)) ?>"><?= bl_escape($case['title']) ?></a></h2><p><?= bl_escape($case['excerpt']) ?></p><a class="bl-text-link" href="<?= bl_escape(bl_case_url($case)) ?>">Read the application <?= bl_icon('arrow-up-right') ?></a></article>
